#!/bin/bash
set -e
# get any changes others have published before building on top of them
cd public
# public/ is generated by hugo, so discard leftovers from any earlier failed run
git reset --hard
git clean -fd
git pull --rebase
cd ..
hugo -e production
cd public
git add -A
if git diff --cached --quiet; then
    echo "nothing to publish"
    exit 0
fi
git commit -m 'update'
git push
